permission_denials.command:
python3 - <<'EOF'
import json,re,sys
p="journals/2026-08-19-shop-wide-latency-chaos.md"
txt=open(p).read()
fm=txt.split("---\n")[1]
try:
    import yaml
except ImportError:
    print("no pyyaml"); sys.exit(0)
doc=yaml.safe_load(fm)
schema=json.load(open(".claude/skills/investigate/journal.schema.json"))
try:
    import jsonschema
    jsonschema.Draft202012Validator(schema).validate(doc); print("schema OK")
except ImportError:
    print("no jsonschema; keys:", list(doc))
ids={e["id"] for e in doc["evidence"]}
for h in doc["hypotheses"]:
    for r in h["evidence_for"]+h["evidence_against"]:
        assert r in ids, r
print("refs OK; verdict", doc["verdict"], "rc->", doc["root_cause"]["hypothesis"])
EOF
